function M.guard()
    local p, r = M.thief()
    if not p then return false end
    local bat = G.gear("Bat")
    if not bat then say(__T["You need a Bat to stop thieves"]) return false end
    local me = hrp()
    if not me then return false end
    S.task = __T["Stopping thief "] .. p.DisplayName
    if not M.wantReturn and on("x_return") then M.wantReturn = me.CFrame end
    M.unseat()
    M.equip(bat)
    M.guarding = true
    local c = r.Parent
    local lock = RunService.Heartbeat:Connect(function()
        local m = hrp()
        if not (m and r.Parent) then return end
        local v = r.AssemblyLinearVelocity
        local tp = r.Position + Vector3.new(v.X, 0, v.Z) * 0.12
        local look = Vector3.new(v.X, 0, v.Z)
        if look.Magnitude < 1 then look = r.CFrame.LookVector * Vector3.new(1, 0, 1) end
        local pos = tp + look.Unit * 2.2
        m.CFrame = CFrame.lookAt(pos, Vector3.new(tp.X, pos.Y, tp.Z))
        m.AssemblyLinearVelocity = Vector3.zero
    end)
    local t0, h0 = os.clock(), M.hits
    while RUNNING and os.clock() - t0 < 10 and c.Parent and c:GetAttribute("Carrying") do
        if bat.Parent ~= char() then M.equip(bat) end
        pcall(function() bat:Activate() end)
        task.wait(0.3)
    end
    lock:Disconnect()
    M.guarding = false
    M.unequip()
    if not c:GetAttribute("Carrying") then say(__T["Stopped "] .. p.DisplayName .. " (" .. (M.hits - h0) .. __T[" hits)"]) M.thiefName = nil end
    return true
end
