            for _, f in ipairs(fr and fr:GetChildren() or {}) do
                local p = f:FindFirstChild("Harvest", true)
                if p and p.Enabled and not p:GetAttribute("Unripe") then ripe = true break end
            end
            if not ripe then out[#out + 1] = { s = s, v = v.FruitValue, n = tonumber(s.slot.Name:match("%d+")) } end
        end
    end
    table.sort(out, function(a, b) return a.v < b.v end)
