function M.shopDue()
    if os.clock() - M.lastShop < 20 and (G.restockAt or 0) <= M.lastShop then return false end
    local seeds, ferts = sel("s_seeds"), sel("s_ferts")
    if not next(seeds) and not next(ferts) then return false end
    local cash = G.cash() - (tonumber(val("s_reserve", 0)) or 0)
    local tg = next(seeds) and M.targets() or {}
    if tg[1] ~= nil then
        if G.shop and type(G.shop.Items) == "table" then
            for _, it in ipairs(G.shop.Items) do
                local v = G.VBY[it.Id]
                if seeds[it.Id] and v and v.FruitValue > tg[1] and (tonumber(it.Stock) or 0) > 0 and cash >= (tonumber(it.Price) or 1e18) then return true end
            end
        elseif os.clock() - M.lastShop > 60 then return true end
    end
    local keep = tonumber(val("s_keep", 3)) or 3
    for id in pairs(ferts) do
        if M.fertHave(id) < keep and cash >= (M.FPRICE[id] or 1e18) and os.clock() - M.lastShop > 30 then return true end
    end
    return false
end
function M.buyOnce(verb, id)
    for _ = 1, 2 do
        local c0 = G.cash()
        pcall(function() G.fire("SeedShop", verb, id) end)
        local ok = M.waitFor(function() return G.cash() < c0 end, 1.5)
