function M.shopTrip()
    M.lastShop = os.clock()
    S.task = __T["Buying at the seed shop"]
    M.shopNear()
    local seeds, ferts = sel("s_seeds"), sel("s_ferts")
    local reserve = tonumber(val("s_reserve", 0)) or 0
    local bought = 0
    local items = {}
    for _, it in ipairs((G.shop and G.shop.Items) or {}) do items[#items + 1] = it end
    table.sort(items, function(a, b) return (tonumber(a.Price) or 0) > (tonumber(b.Price) or 0) end)
    local tg = M.targets()
    local cap = tonumber(val("s_maxseeds", 14)) or 14
    for _, it in ipairs(items) do
        local v = G.VBY[it.Id]
        if seeds[it.Id] and v then
            local price = tonumber(it.Price) or 1e18
            for _ = 1, tonumber(it.Stock) or 0 do
                if G.cash() - reserve < price or bought >= cap or tg[1] == nil or v.FruitValue <= tg[1] then break end
                if not M.buyOnce("Buy", it.Id) then break end
                table.remove(tg, 1)
                bought += 1
            end
        end
    end
    local keep = tonumber(val("s_keep", 3)) or 3
    for id in pairs(ferts) do
        for _ = M.fertHave(id) + 1, keep do
            if G.cash() - reserve < (M.FPRICE[id] or 1e18) then break end
            if not M.buyOnce("BuyFert", id) then break end
            bought += 1
        end
    end
    if bought > 0 then say(__T["Bought "] .. bought .. __T[" items"]) end
    return true
end
