        if G.cash() - (tonumber(val("s_reserve", 0)) or 0) >= price[id] then
            pcall(function() G.fire("Gardener", "Buy", id) end)
            task.wait(0.6)
            pcall(function() G.fire("Gardener", "Hire", id) end)
            say(__T["Hired gardener "] .. id)
            return
        end
    end
end
function M.rebirth()
    local r = G.rebirths()
    if r >= 25 then return end
    if G.cash() >= G.rbCost(r) then
        if #G.tools("FruitUid") > 0 then M.rebirthPending = true return end
        local ok2, a, b = pcall(function() return G.invoke("Rebirth") end)
        if ok2 and a then say(__T["Rebirthed! x"] .. tostring(lp:GetAttribute("SellMultiplier"))) end
    end
end
function M.userMoving()
    local h = hum()
    return h and h.MoveDirection.Magnitude > 0.1 and not UserInputService:GetFocusedTextBox()
end
function M.tick()
    local phase, left = G.state()
    if on("p_guard") and phase == "Night" and M.guard() then return true end
    if M.sellNow then M.sellNow = false if M.sell(true) then return true end end
    if on("x_pause") and M.userMoving() and not (phase == "Night" and on("p_steal")) then
        M.wantReturn = nil
        S.task = "Paused while you move"
        return false
    end
    if M.rebirthPending then
        M.rebirthPending = false
        if #G.tools("FruitUid") > 0 then M.sellAt(G.tools("FruitUid"), true) return true end
    end
    if phase == "Night" and on("f_harvest") and M.harvestOne() then return true end
    if on("p_steal") and phase == "Night" and M.stealOne(tonumber(left) or 0) then return true end
    if G.carrying() then M.bankLoot() return true end
    local n, mx = G.bag()
    if on("f_sell") and n >= math.min(mx, tonumber(val("f_sellat", 10)) or 10) and M.sell() then return true end
    if on("f_harvest") and M.harvestOne() then return true end
    if on("f_sell") and n > 0 and n >= mx and M.sell(true) then return true end
    if on("f_plant") and M.plantOne() then return true end
    if on("f_upgrade") and on("f_plant") and os.clock() - (M.upgradeFail or 0) > 30 and M.upgradeOne() then return true end
    if on("s_buy") and M.shopDue() and M.shopTrip() then return true end
    if on("s_padsauto") and M.padOne() then return true end
    if on("s_chest") and M.chestOne() then return true end
    if on("f_water") and M.waterOne() then return true end
    if on("f_tonic") and M.tonicOne() then return true end
    if on("r_auto") and M.rubberOne() then return true end
    if on("r_sell") and M.sellLumps() then return true end
    if on("f_sell") and phase ~= "Night" and M.barnOwned() and (os.clock() - (M.barnAt or 0)) > 30 then
        M.barnAt = os.clock()
        if M.barnSell() then return true end
    end
    return false
end
task.spawn(function()
    while RUNNING do
        local did = false
        local ok, err = pcall(function() did = M.tick() end)
        if not ok then LOG("tick err", err) end
        if not did then
            if M.wantReturn and not M.userMoving() then M.goBack() end
            if S.task ~= "Paused while you move" then S.task = __T["Idle"] end
            task.wait(0.4)
        else
            task.wait(0.05)
        end
    end
end)
