    elseif name == "Seed Shop" then local n = G.npc("DurianWarehouse.ShanaKung") cf = n and G.spotNear(n, 5)
    elseif name == "Rubber Buyer" then local n = G.npc("RubberMarket.Dragon_Girl") cf = n and G.spotNear(n, 5)
    elseif name == "Car Dealer" then local n = Workspace:FindFirstChild("Traveler_Guy") cf = n and G.spotNear(n, 5)
    elseif name == "My Barn" then local b = G.base() local f = b and b.Items:FindFirstChild("Barn") f = f and f:FindFirstChild("Floor") cf = f and f.CFrame + Vector3.new(0, 3.5, 0)
    elseif name == "My Well" then local b = G.base() local w = b and b.Items:FindFirstChild("Well") w = w and w:FindFirstChild("PromptPart") cf = w and CFrame.new(w.Position + Vector3.new(0, 1, 4))
    else
