function V.tag(part, text, color)
    local bb = V.tags[part]
    if not bb or not bb.Parent then
        bb = Instance.new("BillboardGui")
        bb.Size = UDim2.fromOffset(200, 18)
        bb.AlwaysOnTop = true
        bb.StudsOffset = Vector3.new(0, 2, 0)
        bb.MaxDistance = 2000
        local l = Instance.new("TextLabel")
        l.Name = "L"
        l.BackgroundTransparency = 1
        l.Size = UDim2.fromScale(1, 1)
        l.Font = Enum.Font.GothamBold
        l.TextSize = 13
        l.TextStrokeTransparency = 0.3
        l.Parent = bb
        bb.Parent = V.folder
        V.tags[part] = bb
    end
    local sz = tonumber(val("v_size", 13)) or 13
    bb.Adornee = part
    bb.Size = UDim2.fromOffset(sz * 16, sz + 5)
    bb.L.TextSize = sz
    bb.L.Text = text
    bb.L.TextColor3 = color
    bb.Enabled = true
    return bb
end
function V.update()
    local seen = {}
    if on("v_fruit") then
        local muts = sel("v_muts")
        local minkg = tonumber(val("v_minkg", 0)) or 0
        local list = G.fruits()
        table.sort(list, function(a, b) return a.v > b.v end)
        local n = 0
        for _, fr in ipairs(list) do
            if n >= 25 then break end
            local mk = fr.mut or "Normal"
            if (not next(muts) or muts[mk]) and fr.kg >= minkg and (fr.mine or on("v_others")) then
                n += 1
                seen[fr.part] = true
                V.tag(fr.part, string.format("%s%s %.1fkg $%s", fr.mut and (fr.mut .. " ") or "", tostring(fr.id), fr.kg, fmt(fr.v)), V.COL[mk] or V.COL.Normal)
            end
        end
    end
    for part, bb in pairs(V.tags) do if not seen[part] then pcall(function() bb:Destroy() end) V.tags[part] = nil end end
    for _, p in ipairs(Players:GetPlayers()) do
        local c = p ~= lp and p.Character
        local want = c and on("v_thief") and c:GetAttribute("Carrying")
        local h = c and V.hl[c]
        if want and not h then
            h = Instance.new("Highlight")
            h.FillColor = Color3.fromRGB(255, 60, 60)
            h.OutlineColor = Color3.fromRGB(255, 255, 255)
            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            h.Adornee = c
            h.Parent = V.folder
            V.hl[c] = h
        elseif not want and h then
            pcall(function() h:Destroy() end)
            V.hl[c] = nil
        end
    end
end
