        M.codeBusy = true
        task.spawn(function() notify(__T["Redeeming codes..."]) local n = M.codes() M.codeBusy = false notify(n > 0 and (__T["Redeemed "] .. n .. __T[" new codes!"]) or __T["All codes already redeemed"]) end)
    end })
