    CG:AddLabel('<font color="#f5c542"><b>2026-10-27  v1.2</b></font>', true)
    for _, l in ipairs({ __T["~ Best seeds first"], __T["~ Auto tree upgrade"], __T["+ Store seeds"], __T["+ ESP text size"], __T["+ Replace trees"], __T["~ Smarter seed buy"], __T["~ Cleaner tabs"], __T["~ Thief guard fix"], __T["~ Barn storing"], __T["~ Seed shop buys"], __T["~ Never Sell fix"], __T["+ Pause on move"], __T["+ Water by need"], __T["+ Tonic by need"], __T["+ Restock timer"], __T["+ Low graphics"], __T["+ Server hop"], __T["+ Auto refunds"] }) do CG:AddLabel(l, true) end
    CG:AddLabel('<font color="#f5c542"><b>2026-10-27  v1.0</b></font>', true)
