task.spawn(function()
    local cash0
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        local okS, errS = pcall(function()
            local m = os.clock() - S.msgAt < 8 and S.msg or ""
            local t = os.clock() - G.toastAt < 6 and G.toast or ""
            setText(UI.task, "<b>" .. tostring(S.task) .. "</b>" .. (m ~= "" and ("\n" .. m) or "") .. (t ~= "" and ('\n<font color="#9aa0a6">' .. t .. "</font>") or ""))
            if next(G.missing) then
                local miss = {} for k in pairs(G.missing) do miss[#miss + 1] = k end
                setText(UI.task, "<b>" .. tostring(S.task) .. "</b>\n<font color=\"#ff6b6b\">Game updated, paused: " .. table.concat(miss, ", ") .. "</font>")
            end
            local n, mx = G.bag()
            setText(UI.stats, string.format(__T["Cash $%s  ·  Bag %d/%d\nSell bonus x%.2f"], fmt(G.cash()), n, mx, tonumber(lp:GetAttribute("SellMultiplier")) or 1))
            local farming = on("f_harvest") or on("p_steal") or on("f_sell")
            if farming then
                if not S.farmAt then S.farmAt, cash0, S.earned, S.harvested, S.stolen = os.clock(), G.cash(), 0, 0, 0 end
                local hrs = math.max(1 / 3600, (os.clock() - S.farmAt) / 3600)
                setText(UI.sess, string.format(__T["Running %s\nHarvested %d  ·  Stolen %d\nSold $%s  ($%s/hr)"], eta(os.clock() - S.farmAt), S.harvested, S.stolen, fmt(S.earned), fmt(S.earned / hrs)))
            else
                S.farmAt = nil
                setText(UI.sess, __T["Turn on Auto Harvest + Auto Sell to start."])
            end
            local ph, left = G.state()
            local nightIn = ph == "Night" and 0 or (tonumber(left) or 0)
            setText(UI.night, ph == "Night" and string.format('<font color="#ff6b6b"><b>PURGE NOW</b></font>  ·  %s left', eta(left)) or (__T["Purge in "] .. eta(nightIn)))
            local th = M.thief()
            setText(UI.purge, th and ('<font color="#ff6b6b">Thief on your farm!</font>') or __T["Farm is safe"])
            if G.shop and type(G.shop.Items) == "table" then
                local parts = {}
                for _, it in ipairs(G.shop.Items) do if (tonumber(it.Stock) or 0) > 0 then parts[#parts + 1] = tostring(it.Id) .. " x" .. tostring(it.Stock) end end
                local nr = (tonumber(G.shop.NextRestock) or 0) - Workspace:GetServerTimeNow()
                setText(UI.shop, __T["In stock: "] .. (#parts > 0 and table.concat(parts, ", ") or __T["nothing"]) .. __T["\nRestock in "] .. eta(nr))
            else
                setText(UI.shop, __T["Stock shows after the first shop visit."])
            end
            local r = G.rebirths()
                        local owed = tonumber(lp:GetAttribute("GardenerOwed")) or 0
            setText(UI.reb, string.format(__T["Rebirths %d  ·  next $%s"], r, fmt(G.rbCost(r))) .. (owed > 0 and (__T["\nGardener owed $"] .. fmt(owed)) or ""))
            local d = G.day()
            local lines = {}
            for _, v in ipairs(G.VAR) do
                local p = G.price(v.Id, d)
                local col = p >= 1.1 and "#7ED957" or (p <= 0.9 and "#ff6b6b" or "#e0e0e0")
                local best, bd = 0, 0
                for k = 0, 8 do local q = G.price(v.Id, d + k) if q > best then best, bd = q, k end end
                lines[#lines + 1] = string.format('<b>%s</b>  <font color="%s">%d%%</font>\n<font color="#9aa0a6">  best %d%% %s</font>', v.Id, col, math.floor(p * 100 + 0.5), math.floor(best * 100 + 0.5), bd == 0 and "today" or ("in " .. eta((810 - G.now() % 810) + (bd - 1) * 810)))
            end
            setText(UI.prices, table.concat(lines, "\n"))
        end)
        if not okS then S.statusErr = tostring(errS) end
        task.wait(1)
    end
end)
